@startuml

class Take {
  + nbr : int
  + filmed_meters : double
  + reel : string
}

class Setup {
  + code : string
  + photographic_pars : string
}

class Scene {
  + code : string
  + description : string
}

class Internal extends Scene {
  + theater : string
}

class External extends Scene {
  + night_scene : boolean
}

class Location {
  + name : string
  + address : string
  + description : string
}

Take "1..*" -- "1" Setup : associated_to
Setup "1..*" -- "1" Scene : filmed_from
External "0..*" -- "1" Location : located_in

@enduml

